CREATE FUNCTION public.confirm_game_nights(p_trip uuid,p_option integer) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $q$ SELECT trip_private.confirm_game_nights(p_trip,p_option) $q$;
CREATE FUNCTION public.set_game_night_host(p_trip uuid,p_week integer,p_host uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $q$ SELECT trip_private.set_game_night_host(p_trip,p_week,p_host) $q$;
CREATE FUNCTION public.set_first_game(p_trip uuid,p_game integer) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $q$ SELECT trip_private.set_first_game(p_trip,p_game) $q$;
CREATE FUNCTION public.spin_next_game(p_trip uuid) RETURNS TABLE(game_number integer,week_number integer,spin_time timestamptz) LANGUAGE sql SECURITY INVOKER SET search_path=public AS $q$ SELECT * FROM trip_private.spin_next_game(p_trip) $q$;
CREATE FUNCTION public.draw_game_card(p_trip uuid,p_category text) RETURNS bigint LANGUAGE sql SECURITY INVOKER SET search_path=public AS $q$ SELECT trip_private.draw_game_card(p_trip,p_category) $q$;
